mapper.update:
update "h_churn_result"
set churn_rate = #{churnRate},
    top1_reason = #{top1Reason},
    top2_reason = #{top2Reason},
    top3_reason = #{top3Reason}
where result_id = #{resultId}

mapper.select:
select r.result_id, r.username, r.churn_rate, r.top1_reason, r.top2_reason, r.top3_reason, r.churn_date
from (
    select distinct on (username) result_id, username, churn_rate, top1_reason, top2_reason, top3_reason, churn_date
    from "h_churn_result"
    order by username, churn_date desc nulls last, result_id desc
) r

    join "h_member" mem ON r.username = mem.username
    where mem.gym_id = #{gymId}
